	'messages:api-help-param-multi-separate' => 'ar:قيم منفصلة بـ<kbd>|</kbd> أو [[Special:ApiHelp/main#main/datatypes|بديل]].',
	'messages:api-help-param-multi-all' => 'ar:لتحديد كل القيم; استخدم <kbd>$1</kbd>.',
